  1→import { useState, useCallback, useEffect } from 'react';
  2→import { ThemeProvider } from './contexts/ThemeContext';
  3→import { useTheme } from './hooks/useTheme';
  4→import { useSessionId } from './hooks/useSessionId';
  5→import { LanguageProvider } from './contexts/LanguageContext';
  6→import { useTranslation } from './hooks/useTranslation';
  7→import { AgentProvider } from './contexts/AgentContext';
  8→import { ConfigProvider } from './contexts/ConfigContext';
  9→import { ConversationProvider, useConversation } from './contexts/ConversationContext';
 10→import { FileUpload } from './components/FileUpload';
 11→import { QueryEditor } from './components/QueryEditor';
 12→import { ResultsTable } from './components/ResultsTable';
 13→import { ResultMarkdown } from './components/ResultMarkdown';
 14→import { Sidebar } from './components/Sidebar';
 15→import { ErrorMessage } from './components/ErrorMessage';
 16→import { AgentPanel } from './components/AgentPanel';
 17→import { useAgent } from './hooks/useAgent';
 18→import type { TableInfo, QueryResult } from './types';
 19→import './App.css';
 20→
 21→function findDuplicateFileNames(files: File[]): string[] {
 22→  const seen = new Set<string>();
 23→  const duplicates = new Set<string>();
 24→  for (const file of files) {
 25→    if (seen.has(file.name)) {
 26→      duplicates.add(file.name);
 27→    }
 28→    seen.add(file.name);
 29→  }
 30→  return Array.from(duplicates);
 31→}
 32→
 33→function AppContent({
 34→  tables,
 35→  refreshTables,
 36→  sessionId,
 37→}: {
 38→  tables: TableInfo[];
 39→  refreshTables: () => Promise<void>;
 40→  sessionId: string;
 41→}) {
 42→  const { theme, toggleTheme } = useTheme();
 43→  const { language, setLanguage, t } = useTranslation();
 44→  const [queryResult, setQueryResult] = useState<QueryResult | null>(null);
 45→  const [error, setError] = useState<string | { key: string; params: Record<string, string> } | null>(null);
 46→  const [editorQuery, setEditorQuery] = useState<string | undefined>(
 47→    () => tables.length > 0 ? `SELECT * FROM "${tables[0].name}" LIMIT 100` : undefined
 48→  );
 49→  const [sidebarCollapsed, setSidebarCollapsed] = useState(() => window.innerWidth < 768);
 50→  const [agentOpen, setAgentOpen] = useState(true);
 51→  const [pendingSkillCommand, setPendingSkillCommand] = useState<string | null>(null);
 52→
 53→  const conversation = useConversation();
 54→  const { clearMessages, loadMessages } = useAgent();
 55→
 56→  const handleConversationSelect = useCallback(async (id: string) => {
 57→    const messages = await conversation.selectConversation(id);
 58→    loadMessages(messages);
 59→  }, [conversation, loadMessages]);
 60→
 61→  const handleNewConversation = useCallback(() => {
 62→    conversation.startNewConversation();
 63→    clearMessages();
 64→  }, [conversation, clearMessages]);
 65→
 66→  const handleConversationDelete = useCallback(async (id: string) => {
 67→    await conversation.deleteConversation(id);
 68→    if (conversation.activeConversationId === id) {
 69→      clearMessages();
 70→    }
 71→  }, [conversation, clearMessages]);
 72→
 73→  const handleConversationRename = useCallback(async (id: string, title: string) => {
 74→    await conversation.renameConversation(id, title);
 75→  }, [conversation]);
 76→
 77→  useEffect(() => {
 78→    document.title = t('appTitle');
 79→  }, [t]);
 80→
 81→  useEffect(() => {
 82→    if (tables.length === 0) {
 83→      setQueryResult(null);
 84→      setError(null);
 85→      setEditorQuery(undefined);
 86→    }
 87→  }, [tables]);
 88→
 89→  const errorMessage = error
 90→    ? (typeof error === 'string' ? error : t(error.key, error.params))
 91→    : null;
 92→
 93→  const handleAgentToggle = () => {
 94→    setAgentOpen((prev) => !prev);
 95→  };
 96→
 97→  const handleLoadSample = useCallback(async () => {
 98→    setError(null);
 99→    try {
100→      const response = await fetch('/api/upload/sample', { method: 'POST', headers: { 'X-Session-ID': sessionId } });
101→      if (!response.ok) throw new Error('Failed to load sample dataset');
102→      await refreshTables();
103→      setEditorQuery('SELECT * FROM "titanic" LIMIT 100');
104→    } catch (e) {
105→      setError(e instanceof Error ? e.message : 'Failed to load sample dataset');
106→    }
107→  }, [refreshTables, sessionId]);
108→
109→  const handleFileUpload = useCallback(
110→    async (files: File[]) => {
111→      setError(null);
112→
113→      // Check for duplicate filenames within the batch
114→      const batchDuplicates = findDuplicateFileNames(files);
115→      if (batchDuplicates.length > 0) {
116→        setError({ key: 'duplicateFilesInBatch', params: { names: batchDuplicates.join(', ') } });
117→        return;
118→      }
119→
120→      // Check for filenames that match already-uploaded table names
121→      const existingNames = new Set(tables.map((tbl) => tbl.name));
122→      const alreadyUploaded = files.filter((f) => existingNames.has(f.name)).map((f) => f.name);
123→      if (alreadyUploaded.length > 0) {
124→        setError({ key: 'duplicateFilesExist', params: { names: alreadyUploaded.join(', ') } });
125→        return;
126→      }
127→
128→      let lastName = '';
129→      try {
130→        for (const file of files) {
131→          const formData = new FormData();
132→          formData.append('file', file);
133→          const response = await fetch('/api/upload', {
134→            method: 'POST',
135→            headers: { 'X-Session-ID': sessionId },
136→            body: formData,
137→          });
138→          if (!response.ok) {
139→            const errorData = await response.json();
140→            throw new Error(errorData.detail || 'Failed to upload file');
141→          }
142→          const result = await response.json();
143→          // Handle both single table and array of tables (Excel with multiple sheets)
144→          if (Array.isArray(result)) {
145→            lastName = result[result.length - 1]?.name || '';
146→          } else {
147→            lastName = result.name;
148→          }
149→        }
150→        await refreshTables();
151→        if (lastName) {
152→          setEditorQuery(`SELECT * FROM "${lastName}" LIMIT 100`);
153→        }
154→      } catch (e) {
155→        setError(e instanceof Error ? e.message : 'Failed to upload file');
156→      }
157→    },
158→    [refreshTables, sessionId, tables]
159→  );
160→
161→  const handleQueryExecute = useCallback(
162→    async (sql: string) => {
163→      setError(null);
164→      setQueryResult(null);
165→      try {
166→        const start = performance.now();
167→        const response = await fetch('/api/query', {
168→          method: 'POST',
169→          headers: { 'Content-Type': 'application/json', 'X-Session-ID': sessionId },
170→          body: JSON.stringify({ sql }),
171→        });
172→        const elapsed = performance.now() - start;
173→
174→        if (!response.ok) {
175→          const errorData = await response.json();
176→          throw new Error(errorData.detail || 'Query execution failed');
177→        }
178→
179→        const result = await response.json();
180→        setQueryResult({
181→          columns: result.columns,
182→          rows: result.rows,
183→          rowCount: result.rowCount,
184→          executionTimeMs: elapsed,
185→          resultType: result.resultType,
186→        });
187→        await refreshTables();
188→      } catch (e) {
189→        setError(e instanceof Error ? e.message : 'Query execution failed');
190→      }
191→    },
192→    [refreshTables, sessionId]
193→  );
194→
195→  const handleTableClick = useCallback((tableName: string) => {
196→    setEditorQuery(`SELECT * FROM "${tableName}" LIMIT 100`);
197→  }, []);
198→
199→  const handleTableDelete = useCallback(async (tableName: string) => {
200→    if (!confirm(t('deleteTableConfirm', { name: tableName }))) return;
201→    try {
202→      const response = await fetch(`/api/tables/${encodeURIComponent(tableName)}`, {
203→        method: 'DELETE',
204→        headers: { 'X-Session-ID': sessionId },
205→      });
206→      if (!response.ok) throw new Error('Failed to delete table');
207→      await refreshTables();
208→    } catch (e) {
209→      setError(e instanceof Error ? e.message : 'Failed to delete table');
210→    }
211→  }, [refreshTables, t, sessionId]);
212→
213→  const handleDeleteAll = useCallback(async () => {
214→    if (tables.length === 0) return;
215→    if (!confirm(t('deleteAllTablesConfirm'))) return;
216→    try {
217→      for (const table of tables) {
218→        const response = await fetch(`/api/tables/${encodeURIComponent(table.name)}`, {
219→          method: 'DELETE',
220→          headers: { 'X-Session-ID': sessionId },
221→        });
222→        if (!response.ok) throw new Error('Failed to delete table');
223→      }
224→      await refreshTables();
225→    } catch (e) {
226→      setError(e instanceof Error ? e.message : 'Failed to delete tables');
227→    }
228→  }, [tables, refreshTables, t, sessionId]);
229→
230→  const appClass = [
231→    'app',
232→    sidebarCollapsed ? 'app--sidebar-collapsed' : '',
233→  ].filter(Boolean).join(' ');
234→
235→  const themeIcon = theme === 'dark' ? (
236→    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
237→      <circle cx="12" cy="12" r="5" />
238→      <line x1="12" y1="1" x2="12" y2="3" />
239→      <line x1="12" y1="21" x2="12" y2="23" />
240→      <line x1="4.22" y1="4.22" x2="5.64" y2="5.64" />
241→      <line x1="18.36" y1="18.36" x2="19.78" y2="19.78" />
242→      <line x1="1" y1="12" x2="3" y2="12" />
243→      <line x1="21" y1="12" x2="23" y2="12" />
244→      <line x1="4.22" y1="19.78" x2="5.64" y2="18.36" />
245→      <line x1="18.36" y1="5.64" x2="19.78" y2="4.22" />
246→    </svg>
247→  ) : (
248→    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
249→      <path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z" />
250→    </svg>
251→  );
252→
253→  return (
254→    <div className={appClass}>
255→      <div className="app__sidebar-wrapper">
256→        <Sidebar
257→          tables={tables}
258→          onTableClick={handleTableClick}
259→          onTableDelete={handleTableDelete}
260→          onUpload={handleFileUpload}
261→          onDeleteAll={handleDeleteAll}
262→          collapsed={sidebarCollapsed}
263→          onToggle={() => setSidebarCollapsed((prev) => !prev)}
264→          onUseSkill={(name) => setPendingSkillCommand(name)}
265→          activeConversationId={conversation.activeConversationId}
266→          onConversationSelect={handleConversationSelect}
267→          onConversationNew={handleNewConversation}
268→          onConversationDelete={handleConversationDelete}
269→          onConversationRename={handleConversationRename}
270→          conversationRefreshTrigger={conversation.refreshTrigger}
271→        />
272→      </div>
273→      {agentOpen ? (
274→        <div className="app__agent-wrapper">
275→          <div className="app__header">
276→            <h1 className="app__title">{t('appTitle')}</h1>
277→            <div className="app__header-actions">
278→              <button
279→                className="app__lang-toggle"
280→                onClick={() => setLanguage(language === 'en' ? 'zh-TW' : 'en')}
281→                aria-label={language === 'en' ? t('switchToZh') : t('switchToEn')}
282→                title={language === 'en' ? t('switchToZh') : t('switchToEn')}
283→              >
284→                {language === 'en' ? 'EN' : '中'}
285→              </button>
286→              <button
287→                className="app__theme-toggle"
288→                onClick={toggleTheme}
289→                aria-label={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
290→                title={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
291→              >
292→                {themeIcon}
293→              </button>
294→              <button
295→                className="app__agent-toggle app__agent-toggle--active"
296→                onClick={handleAgentToggle}
297→              >
298→                {t('editorMode')}
299→              </button>
300→            </div>
301→          </div>
302→          {errorMessage && (
303→            <ErrorMessage message={errorMessage} onDismiss={() => setError(null)} />
304→          )}
305→          <AgentPanel
306→            tables={tables}
307→            onUpload={handleFileUpload}
308→            onLoadSample={handleLoadSample}
309→            pendingSkillCommand={pendingSkillCommand}
310→            onSkillCommandConsumed={() => setPendingSkillCommand(null)}
311→          />
312→        </div>
313→      ) : (
314→        <div className="app__editor-wrapper">
315→          <div className="app__header">
316→            <h1 className="app__title">{t('appTitle')}</h1>
317→            <div className="app__header-actions">
318→              <button
319→                className="app__lang-toggle"
320→                onClick={() => setLanguage(language === 'en' ? 'zh-TW' : 'en')}
321→                aria-label={language === 'en' ? t('switchToZh') : t('switchToEn')}
322→                title={language === 'en' ? t('switchToZh') : t('switchToEn')}
323→              >
324→                {language === 'en' ? 'EN' : '中'}
325→              </button>
326→              <button
327→                className="app__theme-toggle"
328→                onClick={toggleTheme}
329→                aria-label={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
330→                title={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
331→              >
332→                {themeIcon}
333→              </button>
334→              <button
335→                className="app__agent-toggle"
336→                onClick={handleAgentToggle}
337→              >
338→                {t('agentMode')}
339→              </button>
340→            </div>
341→          </div>
342→          <div className="app__mode-header">
343→            <span className="app__mode-title">{t('editorMode')}</span>
344→          </div>
345→          {errorMessage && (
346→            <ErrorMessage message={errorMessage} onDismiss={() => setError(null)} />
347→          )}
348→          <main className="app__main">
349→            {tables.length === 0 ? (
350→              <div className="app__empty">
351→                <FileUpload onUpload={handleFileUpload} onLoadSample={handleLoadSample} />
352→              </div>
353→            ) : (
354→              <>
355→                <QueryEditor
356→                  onExecute={handleQueryExecute}
357→                  initialQuery={editorQuery}
358→                />
359→                {queryResult?.resultType === 'markdown' ? (
360→                  <ResultMarkdown result={queryResult} />
361→                ) : (
362→                  <ResultsTable result={queryResult} />
363→                )}
364→              </>
365→            )}
366→          </main>
367→        </div>
368→      )}
369→    </div>
370→  );
371→}
372→
373→export default function App() {
374→  const sessionId = useSessionId();
375→  const [tables, setTables] = useState<TableInfo[]>([]);
376→  const [loading, setLoading] = useState(true);
377→  const [error, setError] = useState<string | null>(null);
378→  const refreshTables = useCallback(async () => {
379→    try {
380→      const response = await fetch('/api/tables', {
381→        headers: { 'X-Session-ID': sessionId },
382→      });
383→      if (!response.ok) throw new Error('Failed to fetch tables');
384→      const data = await response.json();
385→      setTables(data);
386→    } catch (e) {
387→      console.error('Failed to refresh tables:', e);
388→    }
389→  }, [sessionId]);
390→
391→  useEffect(() => {
392→    (async () => {
393→      try {
394→        const response = await fetch('/api/health');
395→        if (!response.ok) throw new Error('Backend is not available');
396→        await refreshTables();
397→      } catch (e) {
398→        setError(e instanceof Error ? e.message : 'Failed to connect to backend');
399→      } finally {
400→        setLoading(false);
401→      }
402→    })();
403→  }, [refreshTables]);
404→
405→  if (loading) {
406→    return <div className="app-loading">Connecting to backend...</div>;
407→  }
408→
409→  if (error) {
410→    return (
411→      <div className="app-error">Failed to connect: {error}</div>
412→    );
413→  }
414→
415→  return (
416→    <ConfigProvider>
417→      <LanguageProvider>
418→        <ThemeProvider>
419→          <ConversationProvider>
420→            <AgentProvider refreshTables={refreshTables}>
421→              <AppContent tables={tables} refreshTables={refreshTables} sessionId={sessionId} />
422→            </AgentProvider>
423→          </ConversationProvider>
424→        </ThemeProvider>
425→      </LanguageProvider>
426→    </ConfigProvider>
427→  );
428→}
